 return ch('仓库工作台','Meja kerja gudang')+`<div class="grid kpis">${[['inbound','all','待收货客户','Pelanggan menunggu penerimaan',pending.length],['confirm','pending','待合包 / 复核','Penggabungan / verifikasi',orders.filter(o=>combinedProgress(o)[0]==='pending').length],['ship','paid','待出货订单','Pesanan siap dikirim',orders.filter(o=>combinedProgress(o)[0]==='paid').length],['ship','shipped','运输中订单','Dalam pengiriman',orders.filter(o=>combinedProgress(o)[0]==='shipped').length]].map(([page,f,z,i,n])=>`<button type="button" class="card combined-kpi" data-combined-filter="${f}" data-target-page="${page}">${bi(z,i)}<strong>${n}</strong>${bi('点击处理','Klik untuk memproses')}</button>`).join('')}</div>`+cn('待收货按客户数统计，点开客户查看每个包裹。','Jumlah penerimaan dihitung per pelanggan. Buka pelanggan untuk melihat setiap paket.')+combinedPending()+`<h2>${bi('订单处理','Penanganan pesanan')}</h2>`+combinedOrders(orders.filter(o=>!['delivered','cancelled'].includes(o.status)));
