 if(addressList.owner!==owner)Object.assign(addressList,{owner,query:'',page:1,size:10});
 const q=addressList.query.toLowerCase(),rows=state.addresses.filter(a=>[a.label,a.recipient_name,a.recipient_phone,a.country,a.city,a.address_line,a.postal_code].join(' ').toLowerCase().includes(q));
 const size=[10,20,50].includes(addressList.size)?addressList.size:10,pages=Math.max(1,Math.ceil(rows.length/size));
